From 52ce2d1c5c6d42e904cef481cfc8a4440de09f61 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:23:41 +0100
Subject: [PATCH] applets/taskmanager: show the audio indicator only on the
 playing window

With grouping off, every window of a process got the audio indicator and
volume controls, as streams only carry a PID. When one of these windows
has the stream name or playing track in its title, only that one gets it.

BUG: 375943
---
 applets/taskmanager/qml/PulseAudio.qml |  1 +
 applets/taskmanager/qml/Task.qml       | 55 +++++++++++++++++++++++++-
 2 files changed, 55 insertions(+), 1 deletion(-)

diff --git a/applets/taskmanager/qml/PulseAudio.qml b/applets/taskmanager/qml/PulseAudio.qml
index bbafcd8d0f..98bf362324 100644
--- a/applets/taskmanager/qml/PulseAudio.qml
+++ b/applets/taskmanager/qml/PulseAudio.qml
@@ -96,6 +96,7 @@ QtObject {
             // Determined on demand.
             property int parentPid: -1
             readonly property string appName: model.Client?.properties["application.name"] ?? ""
+            readonly property string name: model.Name
             readonly property string portalAppId: model.Client?.properties["pipewire.access.portal.app_id"] ?? ""
             readonly property bool muted: model.Muted
             // whether there is nothing actually going on on that stream
diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..658169e475 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -55,6 +55,7 @@ PlasmaCore.ToolTipArea {
     readonly property string appName: model.AppName
     readonly property string appId: model.AppId
     readonly property bool isIcon: tasksRoot.iconsOnly || model.IsLauncher
+    readonly property bool isGroupParent: model.IsGroupParent
     property bool toolTipOpen: false
     property bool inPopup: false
     property bool isWindow: model.IsWindow
@@ -67,6 +68,7 @@ PlasmaCore.ToolTipArea {

     property Item audioStreamIcon: null
     property var audioStreams: []
+    property bool audioStreamsMatchedByTitle: false
     property bool delayAudioStreamIndicator: false
     property bool completed: false
     readonly property bool audioIndicatorsEnabled: Plasmoid.configuration.indicateAudioStreams
@@ -211,6 +213,7 @@ PlasmaCore.ToolTipArea {

     onPidChanged: updateAudioStreams({delay: false})
     onAppNameChanged: updateAudioStreams({delay: false})
+    onIsGroupParentChanged: updateAudioStreams({delay: false})

     onIsWindowChanged: {
         if (model.IsWindow) {
@@ -335,7 +338,30 @@ PlasmaCore.ToolTipArea {
             }
         }

-        task.audioStreams = streams;
+        task.audioStreamsMatchedByTitle = streams.length > 0 && !inPopup && !isGroupParent;
+        task.audioStreams = task.audioStreamsMatchedByTitle ? streamsPlayingInWindow(streams) : streams;
+    }
+
+    // All windows of a process share its audio streams. When a window title names what is
+    // playing, as browsers do with the tab title, show the streams only on that window.
+    function streamsPlayingInWindow(streams: var): var {
+        const otherTitles = [];
+        for (let i = 0; i < tasksModel.count; ++i) {
+            const index = tasksModel.makeModelIndex(i);
+            if (i !== task.index && tasksModel.data(index, TaskManager.AbstractTasksModel.AppPid) === model.AppPid) {
+                otherTitles.push(tasksModel.data(index, Qt.DisplayRole) ?? "");
+            }
+        }
+        if (!otherTitles.length) {
+            return streams;
+        }
+
+        const track = mpris2Source.playerForLauncherUrl(model.LauncherUrlWithoutIcon, model.AppPid)?.track;
+        return streams.filter(stream => {
+            const names = [stream.name, track].filter(name => !!name);
+            const isPlayingIn = title => names.some(name => title.includes(name));
+            return isPlayingIn(model.display ?? "") || !otherTitles.some(isPlayingIn);
+        });
     }

     function toggleMuted(): void {
@@ -390,6 +416,33 @@ PlasmaCore.ToolTipArea {
         }
     }

+    Connections {
+        target: tasksModel
+        enabled: task.audioStreamsMatchedByTitle
+        function onDataChanged(topLeft: var, bottomRight: var, roles: var): void {
+            if (roles.length === 0 || roles.includes(Qt.DisplayRole)) {
+                task.updateAudioStreams({delay: false});
+            }
+        }
+        function onRowsInserted(): void {
+            task.updateAudioStreams({delay: false});
+        }
+        function onRowsRemoved(): void {
+            task.updateAudioStreams({delay: false});
+        }
+    }
+
+    Connections {
+        target: mpris2Source
+        enabled: task.audioStreamsMatchedByTitle
+        function onRowsInserted(): void {
+            task.updateAudioStreams({delay: false});
+        }
+        function onDataChanged(): void {
+            task.updateAudioStreams({delay: false});
+        }
+    }
+
     TapHandler {
         id: menuTapHandler
         acceptedButtons: Qt.LeftButton
-- 
